using System;using System.Drawing;using System.Drawing.Imaging;using System.Collections.Generic;
public class HudV2 {
 public class Part {public List<int> P=new List<int>();public Rectangle R;}
 public static byte[] Read(Bitmap b){var d=b.LockBits(new Rectangle(0,0,b.Width,b.Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);byte[] a=new byte[d.Stride*b.Height];System.Runtime.InteropServices.Marshal.Copy(d.Scan0,a,0,a.Length);b.UnlockBits(d);return a;}
