 public static List<Part> Parts(byte[] a,int w,int h){var seen=new bool[w*h];var list=new List<Part>();for(int i=0;i<w*h;i++){if(seen[i]||a[i*4+3]<140)continue;var p=new Part();var q=new Queue<int>();q.Enqueue(i);seen[i]=true;int l=w,r=0,t=h,b=0;while(q.Count>0){int k=q.Dequeue(),x=k%w,y=k/w;p.P.Add(k);l=Math.Min(l,x);r=Math.Max(r,x);t=Math.Min(t,y);b=Math.Max(b,y);foreach(int j in new int[]{k-1,k+1,k-w,k+w}){if(j<0||j>=w*h||seen[j]||Math.Abs(j%w-x)>1||a[j*4+3]<140)continue;seen[j]=true;q.Enqueue(j);}}if(p.P.Count>500){p.R=Rectangle.FromLTRB(Math.Max(0,l-3),Math.Max(0,t-3),Math.Min(w,r+4),Math.Min(h,b+4));list.Add(p);}}list.Sort((x,y)=>y.P.Count.CompareTo(x.P.Count));return list;}
 public static byte[] Extract(byte[] a,int w,Part p,Rectangle rect){var o=new byte[rect.Width*rect.Height*4];foreach(int k in p.P)for(int dy=-2;dy<=2;dy++)for(int dx=-2;dx<=2;dx++){int x=k%w+dx,y=k/w+dy;if(!rect.Contains(x,y))continue;Array.Copy(a,(y*w+x)*4,o,((y-rect.Y)*rect.Width+x-rect.X)*4,4);}return o;}
 public static Rectangle Mask(byte[] a,byte[] m,int w,int h,int sx,int sy,int channel){var q=new Queue<int>();var seen=new bool[w*h];q.Enqueue(sy*w+sx);seen[sy*w+sx]=true;int l=w,r=0,t=h,b=0,n=0;while(q.Count>0){int k=q.Dequeue(),x=k%w,y=k/w;int at=k*4;if(a[at+3]<180||a[at+2]<180||a[at+1]<128)continue;m[at+channel]=255;m[at+3]=255;n++;l=Math.Min(l,x);r=Math.Max(r,x);t=Math.Min(t,y);b=Math.Max(b,y);foreach(int j in new int[]{k-1,k+1,k-w,k+w}){if(j<0||j>=w*h||seen[j]||Math.Abs(j%w-x)>1)continue;seen[j]=true;q.Enqueue(j);}}if(n<20000||n>120000)throw new Exception("Unexpected pill area "+n);return Rectangle.FromLTRB(l,t,r+1,b+1);}

 public static void Normalize(string root){string dir=System.IO.Path.Combine(root,"derived"),file=System.IO.Path.Combine(dir,"energy.png"),maskFile=System.IO.Path.Combine(dir,"energy_mask.png");byte[] a,m;int w,h;using(var b=new Bitmap(file)){w=b.Width;h=b.Height;a=Read(b);}using(var b=new Bitmap(maskFile))m=Read(b);Save(a,w,h,System.IO.Path.Combine(dir,"energy_empty_reference.png"));int ax=w,bx=0,ay=h,by=0,cx=w,dx=0;for(int k=0;k<w*h;k++){if(m[k*4+2]>128){ax=Math.Min(ax,k%w);bx=Math.Max(bx,k%w);ay=Math.Min(ay,k/w);by=Math.Max(by,k/w);}if(m[k*4]>128){cx=Math.Min(cx,k%w);dx=Math.Max(dx,k%w);}}int shift=(int)Math.Round((cx+dx-ax-bx)*0.5);var patch=Rectangle.FromLTRB(ax-20,ay-20,bx+21,by+21);var original=(byte[])a.Clone();for(int y=patch.Top;y<patch.Bottom;y++)Array.Copy(original,(y*w+patch.Left)*4,a,(y*w+patch.Left+shift)*4,patch.Width*4);for(int k=0;k<w*h;k++){m[k*4]=0;m[k*4+3]=(byte)Math.Max(m[k*4+1],m[k*4+2]);}for(int y=ay;y<=by;y++)for(int x=ax;x<=bx;x++){byte v=m[(y*w+x)*4+2];int at=(y*w+x+shift)*4;m[at]=v;m[at+3]=v;}Save(a,w,h,file);Save(m,w,h,maskFile);string gdFile=System.IO.Path.Combine(root,"regions.gd"),gd=System.IO.File.ReadAllText(gdFile);var matches=System.Text.RegularExpressions.Regex.Matches(gd,@"Vector4\([^\r\n]+\)");string old=matches[2].Value;var culture=System.Globalization.CultureInfo.InvariantCulture;string replacement="Vector4("+((ax+shift)/(double)w).ToString("F7",culture)+","+(ay/(double)h).ToString("F7",culture)+","+((bx-ax+1)/(double)w).ToString("F7",culture)+","+((by-ay+1)/(double)h).ToString("F7",culture)+")";gd=gd.Replace(old,replacement)+"const EMPTY_PILL := "+old+"\n";System.IO.File.WriteAllText(gdFile,gd);}
 public static void Menus(string root){string dir=System.IO.Path.Combine(root,"derived");System.IO.Directory.CreateDirectory(dir);using(var b=new Bitmap(System.IO.Path.Combine(root,"originals","exit_restart.png"))){var a=Read(b);var list=Parts(a,b.Width,b.Height);list=list.GetRange(0,2);list.Sort((x,y)=>x.R.X.CompareTo(y.R.X));for(int i=0;i<2;i++){var p=list[i];Save(Extract(a,b.Width,p,p.R),p.R.Width,p.R.Height,System.IO.Path.Combine(dir,i==0?"exit.png":"restart.png"));}}using(var b=new Bitmap(System.IO.Path.Combine(root,"originals","settings.png"))){var a=Read(b);var p=Parts(a,b.Width,b.Height)[0];Save(Extract(a,b.Width,p,p.R),p.R.Width,p.R.Height,System.IO.Path.Combine(dir,"settings.png"));}}
 public static void Run(string root){string dir=System.IO.Path.Combine(root,"derived");System.IO.Directory.CreateDirectory(dir);var gd="extends RefCounted\n";foreach(string id in new string[]{"exit","restart","settings","cursor","energy"}){using(var b=new Bitmap(System.IO.Path.Combine(root,"originals",id+".png"))){var a=Read(b);var parts=Parts(a,b.Width,b.Height);if(id!="energy"){var p=parts[0];Save(Extract(a,b.Width,p,p.R),p.R.Width,p.R.Height,System.IO.Path.Combine(dir,id+".png"));continue;}var whole=parts[0].R;foreach(var p in parts)whole=Rectangle.Union(whole,p.R);Save(Extract(a,b.Width,parts[0],whole),whole.Width,whole.Height,System.IO.Path.Combine(dir,"energy.png"));gd+="const SOURCE_SIZE := Vector2("+whole.Width+","+whole.Height+")\nconst RAYS := [\n";for(int i=1;i<parts.Count;i++){var p=parts[i];Save(Extract(a,b.Width,p,p.R),p.R.Width,p.R.Height,System.IO.Path.Combine(dir,"ray_"+(i-1)+".png"));gd+="    Rect2("+(p.R.X-whole.X)+","+(p.R.Y-whole.Y)+","+p.R.Width+","+p.R.Height+"),\n";}gd+="]\nconst PILLS := [\n";var mask=new byte[a.Length];for(int i=0;i<3;i++){var r=Mask(a,mask,b.Width,b.Height,750+i*460,400,2-i);gd+="    Vector4("+((r.X-whole.X)/(double)whole.Width).ToString("F7",System.Globalization.CultureInfo.InvariantCulture)+","+((r.Y-whole.Y)/(double)whole.Height).ToString("F7",System.Globalization.CultureInfo.InvariantCulture)+","+(r.Width/(double)whole.Width).ToString("F7",System.Globalization.CultureInfo.InvariantCulture)+","+(r.Height/(double)whole.Height).ToString("F7",System.Globalization.CultureInfo.InvariantCulture)+"),\n";}gd+="]\n";var cropped=new byte[whole.Width*whole.Height*4];for(int y=0;y<whole.Height;y++)Array.Copy(mask,((y+whole.Y)*b.Width+whole.X)*4,cropped,y*whole.Width*4,whole.Width*4);Save(cropped,whole.Width,whole.Height,System.IO.Path.Combine(dir,"energy_mask.png"));}}
 System.IO.File.WriteAllText(System.IO.Path.Combine(root,"regions.gd"),gd);}
}
